}

class PageUtil {

    /*
    PageUtil class is a versatile utility for handling pagination and search functionalities in an efficient and convenient manner.
    */

    let data: ArrayList<Int64>
    let page_size: Int64
    let total_items: Int64
    let total_pages: Int64

    public init(data: ArrayList<Int64>, page_size: Int64) {
        /*
        Initialize the PageUtil object with the given data and page size.
        :param data: ArrayList<Int64>, the data to be paginated
        :param page_size: Int64, the number of items per page
        */
        this.data = data
        this.page_size = page_size
        this.total_items = data.size
        this.total_pages = (this.total_items + page_size - 1) / page_size
    }

    public func get_page(page_number: Int64): ArrayList<Int64> {
        /*
        Retrieve a specific page of data.
        :param page_number: Int64, the page number to fetch
        :return: ArrayList<Int64>, the data on the specified page
        >>> page_util = PageUtil(ArrayList<Int64>([1, 2, 3, 4]), 1)
        >>> page_util.get_page(1)
        [1]

        */
        if page_number < 1 || page_number > this.total_pages {
            return ArrayList<Int64>()
        }

        let start_index: Int64 = (page_number - 1) * this.page_size
        var end_index: Int64 = start_index + this.page_size
        if end_index > this.total_items {
            end_index = this.total_items
        }

        if end_index <= start_index {
            return ArrayList<Int64>()
        }

        let r: Range<Int64> = start_index..=(end_index - 1) : 1
        return this.data.slice(r)
    }

    public func get_page_info(page_number: Int64): Option<PageInfo> {
        /*
        Retrieve information about a specific page.
        :param page_number: Int64, the page number to fetch information about
        :return: Option<PageInfo>, containing page information such as current page number, total pages, etc.
        >>> page_util = PageUtil(ArrayList<Int64>([1, 2, 3, 4]), 1)
        >>> page_util.get_page_info(1)
        >>> PageInfo(1, 1, 4, 4, false, true, ArrayList<Int64>([1]))

        */
        if page_number < 1 || page_number > this.total_pages {
            return None
        }

        let start_index: Int64 = (page_number - 1) * this.page_size
        var end_index: Int64 = start_index + this.page_size
        if end_index > this.total_items {
            end_index = this.total_items
        }

        var page_data: ArrayList<Int64>
        if end_index <= start_index {
            page_data = ArrayList<Int64>()
        } else {
            let r: Range<Int64> = start_index..=(end_index - 1) : 1
            page_data = this.data.slice(r)
        }

        let info = PageInfo(
            page_number,
            this.page_size,
            this.total_pages,
            this.total_items,
            page_number > 1,
            page_number < this.total_pages,
            page_data
        )
        return Some(info)
    }

    public func search(keyword: String): SearchInfo {
        /*
        Search for items in the data that contain the given keyword.
        :param keyword: String, the keyword to search for
        :return: SearchInfo, containing search information such as total results and matching items
        >>> page_util = PageUtil(ArrayList<Int64>([1, 2, 3, 4]), 1)
        >>> page_util.search("1")
        >>> SearchInfo("1", 1, 1, ArrayList<Int64>([1]))

        */
        var results: ArrayList<Int64> = ArrayList<Int64>()
        var it = this.data.iterator()
        for (item in it) {
            let s: String = "${item}"
            if s.contains(keyword) {
                results.add(item)
            }
        }

        let num_results: Int64 = results.size
        var num_pages: Int64 = 0
        if this.page_size > 0 {
            num_pages = (num_results + this.page_size - 1) / this.page_size
        } else {
            num_pages = 0
        }

        return SearchInfo(keyword, num_results, num_pages, results)
    }
}

class PersonRequest {

    /*
    This class validates input personal information data and sets invalid fields to None based on specific rules.
    */

    let name: Option<String>
    let sex: Option<String>
    let phoneNumber: Option<String>

    public init(name: String, sex: String, phoneNumber: String) {
        /*
        Initialize PersonRequest object with the provided information.
        */
        this.name = _validate_name(name)
        this.sex = _validate_sex(sex)
        this.phoneNumber = _validate_phoneNumber(phoneNumber)
    }

    public static func _validate_name(name: String): Option<String> {
        /*
        Validate the name and return it. If name is empty or exceeds 33 characters in length, set to None.
        */
        if (name.isEmpty()) {
            return None
        }
        if (name.size > 33) {
            return None
        }
        return Some(name)
    }

    public static func _validate_sex(sex: String): Option<String> {
        /*
        Validate the sex and return it. If sex is not Man, Woman, or UGM, set to None.
        */
        if (sex == "Man" || sex == "Woman" || sex == "UGM") {
            return Some(sex)
        }
        return None
    }

    public static func _validate_phoneNumber(phoneNumber: String): Option<String> {
        /*
        Validate the phone number and return it. If phoneNumber is empty or not an 11 digit number, set to None.
        */
        if (phoneNumber.isEmpty()) {
            return None
        }
        if (phoneNumber.size != 11) {
            return None
        }
        // Ensure all characters are ASCII digits
        let allDigits: Bool = phoneNumber.runes().all({ c: Rune => c >= r'0' && c <= r'9' })
        if (!allDigits) {
            return None
        }
        return Some(phoneNumber)
    }
}

import std.collection.ArrayList

class PushBoxGame {

    /*
    This class implements a functionality of a sokoban game, where the player needs to move boxes to designated targets in order to win.
    */

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        /*
        Initialize the push box game with the map and various attributes.
        :param map: ArrayList<ArrayList<String>>, the map of the push box game, represented as a list of strings. 
            Each character on the map represents a different element, including the following:
            - '#' represents a wall that neither the player nor the box can pass through;
            - 'O' represents the initial position of the player;
            - 'G' represents the target position;
            - 'X' represents the initial position of the box.
        >>> map = ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])
        >>> game = PushBoxGame(map) 
        */
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            /*
            Initialize the game by setting the positions of the player, targets, and boxes based on the map.
            >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
            >>> game.targets
            [[3, 3]]
            >>> game.boxes
            [[2, 2]]
            >>> game.player_row
            1
            >>> game.player_col
            1
            */
            var r: Int64 = 0
            while (r < this.map.size) {
                var c: Int64 = 0
                let row = this.map[r]
                while (c < row.size) {
                    let cell = row[c]
                    if (cell == "O") {
                        this.player_row = r
                        this.player_col = c
                    } else if (cell == "G") {
                        this.targets.add(ArrayList<Int64>([r, c]))
                        this.target_count = this.target_count + 1
                    } else if (cell == "X") {
                        this.boxes.add(ArrayList<Int64>([r, c]))
                    }
                    c = c + 1
                }
                r = r + 1
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        /*
        Check if the game is won. The game is won when all the boxes are placed on target positions.
        And update the value of this.is_game_over.
        :return this.is_game_over: true if all the boxes are placed on target positions, or false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])])) 
        >>> game.check_win()
        false
        */
        var box_on_target_count: Int64 = 0
        var i: Int64 = 0
        while (i < this.boxes.size) {
            let b = this.boxes[i]
            // targets.contains uses element equality; ArrayList<Int64> supports Equatable when elements are Equatable
            if (this.targets.contains(b)) {
                box_on_target_count = box_on_target_count + 1
            }
            i = i + 1
        }
        this.is_game_over = (box_on_target_count == this.target_count)
        return this.is_game_over
    }

    // Utility to find index of a box at given row/col; returns -1 if not found.
    func findBoxIndex(row: Int64, col: Int64): Int64 {
        var i: Int64 = 0
        while (i < this.boxes.size) {
            let b = this.boxes[i]
            if (b[0] == row && b[1] == col) {
                return i
            }
            i = i + 1
        }
        return -1
    }

    public func move(direction: String): Bool {
        /*
        Move the player based on the specified direction and check if the game is won.
        :param direction: String, the direction of the player's movement. 
            It can be 'w', 's', 'a', or 'd' representing up, down, left, or right respectively.

        :return: true if the game is won, false otherwise.
        >>> game = PushBoxGame(ArrayList<ArrayList<String>>([ArrayList<String>(["#", "#", "#", "#", "#"]), ArrayList<String>(["#", "O", " ", " ", "#"]), ArrayList<String>(["#", " ", "X", " ", "#"]), ArrayList<String>(["#", " ", " ", "G", "#"]), ArrayList<String>(["#", "#", "#", "#", "#"])]))       
        >>> game.print_map()
        # # # # # 
        # O     #
        #   X   #
        #     G #
        # # # # #
        >>> game.move('d')
        false
        >>> game.move('s')   
        false
        >>> game.move('a')   
        false
        >>> game.move('s') 
        false
        >>> game.move('d') 
        true
        */
        var new_player_row = this.player_row
        var new_player_col = this.player_col

        if (direction == "w") {
            new_player_row = new_player_row - 1
        } else if (direction == "s") {
            new_player_row = new_player_row + 1
        } else if (direction == "a") {
            new_player_col = new_player_col - 1
        } else if (direction == "d") {
            new_player_col = new_player_col + 1
        }

        // Blocked by wall?
        if (this.map[new_player_row][new_player_col] != "#") {
            // Check if there's a box at the new player position
            let boxIdx = this.findBoxIndex(new_player_row, new_player_col)
            if (boxIdx >= 0) {
                let new_box_row = new_player_row + (new_player_row - this.player_row)
                let new_box_col = new_player_col + (new_player_col - this.player_col)

                if (this.map[new_box_row][new_box_col] != "#") {
                    // Move box forward
                    this.boxes[boxIdx] = ArrayList<Int64>([new_box_row, new_box_col])
                    // Move player into the vacated position
                    this.player_row = new_player_row
                    this.player_col = new_player_col
                }
            } else {
                // Move player to empty cell
                this.player_row = new_player_row
                this.player_col = new_player_col
            }
        }

        return this.check_win()
    }

    public func print_map() {
        // Render the map with current player and boxes, spaced like the sample.
        var r: Int64 = 0
        while (r < this.map.size) {
            var c: Int64 = 0
            let row = this.map[r]
            while (c < row.size) {
                var ch = row[c]
                if (r == this.player_row && c == this.player_col) {
                    ch = "O"
                } else {
                    // Check if a box occupies this cell
                    var j: Int64 = 0
                    var hasBox = false
                    while (j < this.boxes.size) {
                        let b = this.boxes[j]
                        if (b[0] == r && b[1] == c) {
                            hasBox = true
                            break
                        }
                        j = j + 1
                    }
                    if (hasBox) {
                        ch = "X"
                    }
                }
                print(ch)
                print(" ")
                c = c + 1
            }
            println("")
            r = r + 1
        }
    }
}

import std.regex.Regex
import std.collection.ArrayList

class RegexUtils {

    /*
    The class provides to match, find all occurrences, split, and substitute text using regular expressions. It also includes predefined patterns, validating phone numbers and extracting email addresses.
    */

    public func match_regex(pattern: String, text: String): Bool {
        /*
        Check if the text matches the regular expression
        :param pattern: String, Regular expression pattern
        :param text: String, Text to match
        :return: true or false, representing whether the text matches the regular expression or not
        >>> ru = RegexUtils()
        >>> ru.match_regex(#'\b\d{3}-\d{3}-\d{4}\b'#, "123-456-7890")
        true
        */
        let r = Regex(pattern)
        return r.matches(text)
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        /*
        Find all matching substrings and return a list of all matching substrings
        :param pattern: String, Regular expression pattern
        :param text: String, Text to match
        :return: list of string, List of all matching substrings
        >>> ru = RegexUtils()
        >>> ru.findall(#'\b\d{3}-\d{3}-\d{4}\b'#, "123-456-7890 abiguygusu 876-286-9876 kjgufwycs 987-762-9767")
        ['123-456-7890', '876-286-9876', '987-762-9767']
        */
        let r = Regex(pattern)
        var res = ArrayList<String>()
        for (md in r.findAll(text)) {
            res.add(md.matchString())
        }
        return res
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        /*
        Split text based on regular expression patterns and return a list of substrings
        :param pattern: String, Regular expression pattern
        :param text: String, Text to be split
        :return: list of string, List of substrings after splitting
        >>> ru = RegexUtils()
        >>> ru.split(#'\b\d{3}-\d{3}-\d{4}\b'#, "123-456-7890 abiguygusu 876-286-9876 kjgufwycs 987-762-9767")
        ['', ' abiguygusu ', ' kjgufwycs ', '']
        */
        let r = Regex(pattern)
        var res = ArrayList<String>()
        for (s in r.split(text)) {
            res.add(s)
        }
        return res
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        /*
        Replace the substring matched by a regular expression with the specified string
        :param pattern: String, Regular expression pattern
        :param replacement: Text to replace with
        :param text: String, Text to be replaced
        :return: String, Text after replacement
        >>> ru = RegexUtils()
        >>> ru.sub(#'\b\d{3}-\d{3}-\d{4}\b'#, 'phone num',  "123-456-7890 abiguygusu 876-286-9876 kjgufwycs 987-762-9767")
        'phone num abiguygusu phone num kjgufwycs phone num'
        */
        let r = Regex(pattern)
        return r.replaceAll(text, replacement)
    }

    public func generate_email_pattern(): String {
        /*
        Generate regular expression patterns that match email addresses
        :return: String, regular expression patterns that match email addresses
        >>> ru = RegexUtils()
        >>> ru.generate_email_pattern()
        '\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'
        */
        return #'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'#
    }

    public func generate_phone_number_pattern(): String {
        /*
        Generate regular expression patterns that match phone numbers
        :return: String, regular expression patterns that match phone numbers
        >>> ru = RegexUtils()
        >>> ru.generate_phone_number_pattern()
        '\b\d{3}-\d{3}-\d{4}\b'
        */
        return #'\b\d{3}-\d{3}-\d{4}\b'#
    }

    public func generate_split_sentences_pattern(): String {
        /*
        Generate regular expression patterns that match the middle characters of two sentences
        :return: String, regular expression patterns that match the middle characters of two sentences
        >>> ru = RegexUtils()
        >>> ru.generate_split_sentences_pattern()
        '[.!?][\s]{1,2}(?=[A-Z])'
        */
        return #'[.!?][\s]{1,2}(?=[A-Z])'#
    }

    public func split_sentences(text: String): ArrayList<String> {
        /*
        Split the text into a list of sentences without Punctuation except the last sentence
        :param text: Text to be split
        :return: Split Text List
        >>> ru = RegexUtils()
        >>> ru.split_sentences("Aaa. Bbbb? Ccc!")
        ['Aaa', 'Bbbb', 'Ccc!']
        */
        let pattern = self.generate_split_sentences_pattern()
        return self.split(pattern, text)
    }

    public func validate_phone_number(phone_number: String): Bool {
        /*
        Verify if the phone number is valid
        :param phone_number: Phone number to be verified
        :return: true or false, indicating whether the phone number is valid
        >>> ru = RegexUtils()
        >>> ru.validate_phone_number("123-456-7890")
        true
        */
        let pattern = self.generate_phone_number_pattern()
        return self.match_regex(pattern, phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        /*
        Extract all email addresses from the text
        :param text: String, input text
        :return: list of string, All extracted email addresses
        >>> ru = RegexUtils()
        >>> ru.extract_email("abcdefg@163.com ygusyfysy@126.com wljduyuv@qq.com")
        ['abcdefg@163.com', 'ygusyfysy@126.com', 'wljduyuv@qq.com']
        */
        let pattern = self.generate_email_pattern()
        return self.findall(pattern, text)
    }
}

class RPGCharacter {

    /*
    The class represents a role-playing game character, which allows to attack other characters, heal, gain experience, level up, and check if the character is alive.
    */

    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        /*
        Initialize an RPG character object.
        :param name: String, the name of the character.
        :param hp: Int64, The health points of the character.
        :param attack_power: Int64, the attack power of the character.
        :param defense: Int64, the defense points of the character.
        :param level: Int64, the level of the character. Default is 1.
        */
        this.name = name
        this.hp = hp
        this.attack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        /*
        Attack another character. The damage caused needs to offset the defense value.
        :param other_character: String, The character being attacked.
        >>> player_1 = RPGCharacter('player 1', 100, 10, 3)
        >>> player_2 = RPGCharacter('player 2', 100, 7, 2)
        >>> player_1.attack(player_2)
        >>> player_2.hp
        92
        */
        var damage = this.attack_power - other_character.defense
        if (damage < 1) {
            damage = 1
        }
        other_character.hp -= damage
    }

    public func heal(): Int64 {
        /*
        Heal the character with 10 hp and the max hp is 100.
        :return: Int64, the current health points after healing.
        >>> player_1 = RPGCharacter('player 1', 93, 10, 3)
        >>> player_1.heal()
        100
        */
        this.hp += 10
        if (this.hp > 100) {
            this.hp = 100
        }
        return this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        /*
        Gain experience points for the character and level_up when the exp has reached the values that is 100 times the current level
        The experience that overflows should be used to calculate the next leve up untill exhausts
        :param amount: Int64, the amount of experience points to gain.
        >>> player_1 = RPGCharacter('player 1', 100, 10, 3)
        >>> player_1.gain_exp(1100)
        >>> player_1.exp
        100
        >>> player_1.level
        5
        */
        var remain = amount
        while (remain != 0) {
            let req = this.level * 100 - this.exp
            if (this.exp + remain >= this.level * 100) {
                remain -= req
                this.level_up()
            } else {
                this.exp += remain
                remain = 0
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        /*
        Level up the character and return to zero experience points, increase hp by 20 points, attack power and defense points by 5 points.
        max level is 100
        :return: (Int64, Int64, Int64, Int64), the new level, health points, attack power, and defense points after leveling up.
        >>> player_1 = RPGCharacter('player 1', 100, 10, 3)
        >>> player_1.level_up()
        (2, 120, 15, 8)
        */
        if (this.level < 100) {
            this.level += 1
            this.exp = 0
            this.hp += 20
            this.attack_power += 5
            this.defense += 5
        }
        return (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        /*
        Check if player is alive.
        :return: true if the hp is larger than 0, or false otherwise.
        >>> player_1 = RPGCharacter('player 1', 100, 10, 3)
        >>> player_1.is_alive()
        true
        */
        return this.hp > 0
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class Server {

    /*
    This is a class as a server, which handles a white list, message sending and receiving, and information display.
    */

    let white_list: ArrayList<Int64>
    let send_struct: HashMap<String, Any>
    let receive_struct: HashMap<String, Any>

    public init() {
        /*
        Initialize the whitelist as an empty list, and initialize the sending and receiving information as an empty map.
        */
        this.white_list = ArrayList<Int64>()
        this.send_struct = HashMap<String, Any>()
        this.receive_struct = HashMap<String, Any>()
    }

    public func add_white_list(addr: Int64): Option<ArrayList<Int64>> {
        /*
        Add an address to the whitelist and do nothing if it already exists
        :param addr: Int64, address to be added
        :return: new whitelist, return None if the address already exists
        >>> server = Server()
        >>> server.add_white_list(88)
        [88]
        */
        if (this.white_list.contains(addr)) {
            return None
        } else {
            this.white_list.add(addr)
            return Some(this.white_list)
        }
    }

    public func del_white_list(addr: Int64): Option<ArrayList<Int64>> {
        /*
        Remove an address from the whitelist and do nothing if it does not exist
        :param addr: Int64, address to be deleted
        :return: new whitelist, return None if the address does not exist
        >>> server.add_white_list(88)
        >>> server.del_white_list(88)
        []
        */
        if (!this.white_list.contains(addr)) {
            return None
        } else {
            // Remove the address by predicate
            this.white_list.removeIf({ x: Int64 => x == addr })
            return Some(this.white_list)
        }
    }

    public func recv(info: HashMap<String, Any>): Any {
        /*
        Receive information containing address and content. If the address is on the whitelist, receive the content; otherwise, do not receive it
        :param info: HashMap<String, Any>, information dictionary containing address and content
        :return: if successfully received, return the content of the information; otherwise, return false
        >>> server.recv(HashMap<String, Any>([("addr",88),("content","abc")]))
        abc
        */
        if (!(info.contains("addr") && info.contains("content"))) {
            return false
        }
        let addrAny = info["addr"]
        match (addrAny) {
            case addr: Int64 =>
                if (!this.white_list.contains(addr)) {
                    return false
                }
                let contentAny = info["content"]
                // Update receive_struct in-place
                this.receive_struct.clear()
                this.receive_struct.add("addr", addr)
                this.receive_struct.add("content", contentAny)
                return contentAny
            case _ =>
                return false
        }
    }

    public func send(info: HashMap<String, Any>): Option<String> {
        /*
        Send information containing address and content
        :param info: HashMap<String, Any>, information dictionary containing address and content
        :return: if successfully sent, return None; otherwise, return "info structure is not correct"
        >>> server.send(HashMap<String, Any>([("addr",66),("content","ABC")]))
        None
        this.send_struct = HashMap<String, Any>([("addr",66),("content","ABC")])
        */
        if (!(info.contains("addr") && info.contains("content"))) {
            return Some("info structure is not correct")
        }
        let addrV = info["addr"]
        let contentV = info["content"]

        // Validate expected types: addr:Int64, content:String
        match (addrV) {
            case _: Int64 => {}
            case _ => return Some("info structure is not correct")
        }
        match (contentV) {
            case _: String => {}
            case _ => return Some("info structure is not correct")
        }

        // Update send_struct in-place
        this.send_struct.clear()
        this.send_struct.add("addr", addrV)
        this.send_struct.add("content", contentV)
        return None
    }

    public func show(type_struct: String): Option<HashMap<String, Any>> {
        /*
        Returns struct of the specified type
        :param type: String, the type of struct to be returned, which can be 'send' or 'receive'
        :return: if type is equal to 'send' or 'receive', return the corresponding struct; otherwise, return None
        >>> server.recv(HashMap<String, Any>([("addr",88),("content","abc")]))
        >>> server.send(HashMap<String, Any>([("addr",66),("content","ABC")]))
        >>> server.show("send")
        {"addr":66,"content":"ABC"}
        */
        if (type_struct == "send") {
            return Some(this.send_struct)
        } else if (type_struct == "receive") {
            return Some(this.receive_struct)
        } else {
            return None
        }
    }
}

import std.collection.HashMap
