        :return: The balance of the vending machine after the coins are inserted, Float64.
        >>> vendingMachine = VendingMachine()
        >>> vendingMachine.insert_coin(1.25)
        1.25

        */
        this.balance = this.balance + amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        /*
        Purchases a product from the vending machine and returns the balance after the purchase and display purchase unsuccessful if the product is out of stock.
        :param item_name: The name of the product to be purchased, String.
        :return: If successful, returns the balance of the vending machine after the product is purchased, Float64,otherwise,returns None.
        >>> vendingMachine = VendingMachine()
        >>> vendingMachine.inventory = HashMap<String, Product>([('Coke', Product(1.25, 10))])
        >>> vendingMachine.balance = 1.25
        >>> vendingMachine.purchase_item('Coke')
        0.0
        >>> vendingMachine.purchase_item('Pizza')
        None

        */
        if (this.inventory.contains(item_name)) {
            let item = this.inventory[item_name]
            if (item.quantity > 0 && this.balance >= item.price) {
                this.balance = this.balance - item.price
                item.quantity = item.quantity - 1
                return Some(this.balance)
            } else {
                return None
            }
        } else {
            return None
        }
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        /*
        Replenishes the inventory of a product already in the vending machine.
        :param item_name: The name of the product to be replenished, String.
        :param quantity: The quantity of the product to be replenished, Int64.
        :return: If the product is already in the vending machine, returns true, otherwise, returns false.
        >>> vendingMachine = VendingMachine()
        >>> vendingMachine.inventory = HashMap<String, Product>([('Coke', Product(1.25, 10))])
        >>> vendingMachine.restock_item('Coke', 10)
        true
        >>> vendingMachine.restock_item('Pizza', 10)
        false

        */
        if (this.inventory.contains(item_name)) {
            this.inventory[item_name].quantity = this.inventory[item_name].quantity + quantity
            return true
        } else {
            return false
        }
    }

    public func display_items(): Option<String> {
        /*
        Displays the products in the vending machine.
        :return: If the vending machine is empty, returns None, otherwise, returns a list of the products in the vending machine, String.
        >>> vendingMachine = VendingMachine()
        >>> vendingMachine.display_items()
        None
        >>> vendingMachine.inventory = HashMap<String, Product>([('Coke', Product(1.25, 10))])
        >>> vendingMachine.display_items()
        'Coke - $1.250000 [10]'

        */
        if (this.inventory.size == 0) {
            return None
        } else {
            var s: String = ""
            var first: Bool = true
            for ((name, product) in this.inventory) {
                let line = name + " - $" + product.price.toString() + " [" + product.quantity.toString() + "]"
                if (first) {
                    s = line
                    first = false
                } else {
                    s = s + "\n" + line
                }
            }
            return Some(s)
        }
    }
}

import std.collection.HashMap

class Product <: Equatable<Product> {

    let name: String
    var quantity: Int64

    public init(name: String, quantity: Int64) {
        this.name = name
        this.quantity = quantity
    }

    public override operator func != (that: Product): Bool {
        return this.name != that.name || this.quantity != that.quantity
    }

    public override operator func == (that: Product): Bool {
        return this.name == that.name && this.quantity == that.quantity
    }
}

class Order <: Equatable<Order> {

    let product_id: Int64
    let quantity: Int64
    var status: String

    public init(product_id: Int64, quantity: Int64, status: String) {
        this.product_id = product_id
        this.quantity = quantity
        this.status = status
    }

    public override operator func != (that: Order): Bool {
        return this.product_id != that.product_id || this.quantity != that.quantity || this.status != that.status
    }

    public override operator func == (that: Order): Bool {
        return this.product_id == that.product_id && this.quantity == that.quantity && this.status == that.status
    }
}

class Warehouse {

    /*
    The class manages inventory and orders, including adding products, updating product quantities, retrieving product quantities, creating orders, changing order statuses, and tracking orders.
    */

    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        /*
        Initialize two fields.
        this.inventory is a dict that stores the products.
        this.inventory = {Product ID: Product}
        this.orders is a dict that stores the products in a order.
        this.orders = {Order ID: Order}
        */
        this.inventory = HashMap<Int64, Product>()  // Product ID: Product
        this.orders = HashMap<Int64, Order>()  // Order ID: Order
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        /*
        Add product to inventory and plus the quantity if it has existed in inventory.
        Or just add new product to dict otherwise.
        :param product_id: Int64
        :param name: String, product name
        :param quantity: Int64, product quantity
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.inventory
        {1: Product('product1', 3)}
        */
        if (this.inventory.contains(product_id)) {
            let p = this.inventory.get(product_id).getOrThrow()
            p.quantity += quantity
        } else {
            this.inventory.add(product_id, Product(name, quantity))
        }
    }

    public func update_product_quantity(product_id: Int64, quantity: Int64): Unit {
        /*
        According to product_id, add the quantity to the corresponding product in inventory.
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.update_product_quantity(1, -1)
        >>> warehouse.inventory
        {1: Product('product1', 2)}
        */
        if (this.inventory.contains(product_id)) {
            let p = this.inventory.get(product_id).getOrThrow()
            p.quantity += quantity
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        /*
        Get the quantity of specific product by product_id.
        :param product_id, Int64
        :return: if the product_id is in inventory then return the corresponding quantity,
                or None otherwise.
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.get_product_quantity(1)
        3
        >>> warehouse.get_product_quantity(2)
        None
        */
        let opt = this.inventory.get(product_id)
        match (opt) {
            case Some(p) => return Some(p.quantity)
            case None => return None
        }
    }

    public func create_order(order_id: Int64, product_id: Int64, quantity: Int64): Bool {
        /*
        Create a order which includes the infomation of product, like id and quantity.
        And put the new order into this.orders.
        The default value of status is 'Shipped'.
        :param order_id: Int64
        :param product_id: Int64
        :param quantity: the quantity of product that be selected.
        :return false: only if product_id is not in inventory or the quantity is not adequate
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.create_order(1, 1, 2)
        >>> warehouse.orders
        {1: Order(1, 2, 'Shipped')}
        >>> warehouse.create_order(1, 2, 2)
        false
        */
        let opt = this.inventory.get(product_id)
        if (opt == None) {
            return false
        }
        let p = opt.getOrThrow()
        if (p.quantity < quantity) {
            return false
        }
        // Deduct inventory and create order with default status "Shipped"
        p.quantity -= quantity
        this.orders.add(order_id, Order(product_id, quantity, "Shipped"))
        return true
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        /*
        Change the status of order if the input order_id is in this.orders.
        :param order_id: Int64
        :param status: String, the state that is going to change to
        :return false: only if the order_id is not in this.orders
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.create_order(1, 1, 2)
        >>> warehouse.change_order_status(1, "done")
        >>> warehouse.orders
        {1: Order(1, 2, 'done')}
        */
        let opt = this.orders.get(order_id)
        if (opt == None) {
            return false
        }
        let order = opt.getOrThrow()
        order.status = status
        return true
    }

    public func track_order(order_id: Int64): Option<String> {
        /*
        Get the status of specific order.
        :param order_id: Int64
        :return None: only if the order_id is not in this.orders.
        >>> warehouse.add_product(1, "product1", 3)
        >>> warehouse.create_order(1, 1, 2)
        >>> warehouse.track_order(1)
        'Shipped'
        */
        let opt = this.orders.get(order_id)
        match (opt) {
            case Some(o) => return Some(o.status)
            case None => return None
        }
    }
}

